(function(){
'use strict';
const C=window.THCore,W=window.THWorkbench;if(!C||!W||!window.TECH_HORIZON)return;
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)],E=C.escape;
const draft=C.storage.get('th-draft',null),D=C.storage.get('th-preview',false)&&draft&&C.validate(draft).length===0?draft:window.TECH_HORIZON;
const base=document.body.dataset.base||'',page=document.body.dataset.page||'',routes=new Set(window.TH_STATIC_ROUTES||[]);
if(C.image(D.config.logoImage,150000))$$('.brand').forEach(brand=>{const old=$('.brand-mark',brand);if(old){const img=document.createElement('img');img.className='brand-mark custom-brand';img.src=D.config.logoImage;img.alt='';img.width=44;img.height=44;old.replaceWith(img);}});
if(page==='home'&&$('.hero-art img'))$('.hero-art img').src=C.image(D.config.heroImage,400000)||base+'assets/horizon-globe.webp';
let toastTimer;function toast(text){const box=$('#toast');if(!box)return;box.textContent=text;box.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.classList.remove('visible'),3500);}
function download(name,text){const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(link.href),10000);}
async function copy(text,field){try{if(navigator.clipboard&&isSecureContext)await navigator.clipboard.writeText(text);else{field.focus();field.select();if(!document.execCommand('copy'))throw Error('copy');}toast('Đã sao chép kết quả.');}catch{field.focus();field.select();toast('Hãy nhấn Ctrl + C hoặc dùng lệnh sao chép trên thiết bị.');}}
function resultUrl(item){if(item.kind==='article')return routes.has(item.id)?base+'bai-viet/'+item.id+'.html':base+'doc-bai.html?id='+encodeURIComponent(item.id);if(item.kind==='term')return base+'thuat-ngu.html#'+item.id;if(item.kind==='journey')return base+'chuyen-de.html#'+item.id;if(item.kind==='page')return base+item.id+'.html';return base+'studio.html#'+item.id;}
const searchDialog=$('#search-dialog'),searchInput=$('#global-search'),searchResults=$('#global-results');let searchKind='all';
if(searchDialog&&searchInput&&searchResults){
 const scopes=document.createElement('div');scopes.className='search-scopes';scopes.setAttribute('role','group');scopes.setAttribute('aria-label','Phạm vi tìm kiếm');
 scopes.innerHTML=[['all','Tất cả'],['article','Cẩm nang'],['term','Thuật ngữ'],['journey','Lộ trình'],['tool','Công cụ'],['page','Trang']].map(([id,name])=>'<button type="button" data-search-scope="'+id+'" aria-pressed="'+(id==='all')+'">'+name+'</button>').join('');searchResults.before(scopes);
 const labels={article:'Cẩm nang',term:'Thuật ngữ',journey:'Lộ trình đọc',tool:'Công cụ Studio',page:'Trang hỗ trợ'},symbols={article:'TH',term:'Aa',journey:'→',tool:'✳',page:'↗'};
 searchInput.setAttribute('aria-controls','global-results');searchResults.removeAttribute('aria-live');
 function renderSearch(){
  const query=searchInput.value,results=W.search(D,query,searchKind);let shown=results.slice(0,16);
  if(!query.trim()&&searchKind==='all')shown=Object.entries({article:4,term:3,journey:2,tool:4,page:2}).flatMap(([kind,count])=>results.filter(r=>r.kind===kind).slice(0,count));
  const groups=[...new Set(shown.map(r=>r.kind))];
  searchResults.innerHTML='<p class="universal-count" id="search-result-status" role="status">'+(query.trim()?results.length+' kết quả · hiển thị '+shown.length:shown.length+' gợi ý để bắt đầu')+'</p>'+groups.map(kind=>'<section class="search-result-group" aria-label="'+labels[kind]+'"><h2>'+labels[kind]+'</h2>'+shown.filter(item=>item.kind===kind).map(item=>'<a class="universal-result" href="'+E(resultUrl(item))+'"><span class="result-symbol result-'+item.kind+'" aria-hidden="true">'+symbols[item.kind]+'</span><span><strong>'+W.highlight(item.title,query)+'</strong><p>'+W.highlight(item.description,query)+'</p></span><b aria-hidden="true">↗</b></a>').join('')+'</section>').join('')+(results.length?'':'<div class="search-empty"><strong>Chưa có kết quả trong phạm vi này.</strong><p>Thử từ khóa ngắn hơn, hoặc mở lại mọi gợi ý.</p><button type="button" class="button button-outline" data-search-reset>Xem mọi gợi ý</button></div>');
  $$('[data-search-scope]',scopes).forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.searchScope===searchKind)));
 }
 window.THSearchRender=renderSearch;
 scopes.addEventListener('click',e=>{const button=e.target.closest('[data-search-scope]');if(button){searchKind=button.dataset.searchScope;renderSearch();}});
 scopes.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;const buttons=$$('[data-search-scope]',scopes),index=buttons.indexOf(document.activeElement);if(index<0)return;e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowRight'?1:buttons.length-1))%buttons.length].focus();});
 searchResults.addEventListener('click',e=>{if(e.target.closest('[data-search-reset]')){searchKind='all';searchInput.value='';renderSearch();searchInput.focus();}});
 searchInput.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='ArrowDown'){e.preventDefault();$('.universal-result',searchResults)?.focus();}if(e.key==='Enter'){const first=$('.universal-result',searchResults);if(first){e.preventDefault();first.click();}}});
 searchResults.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;const links=$$('.universal-result',searchResults),index=links.indexOf(document.activeElement);if(index<0)return;e.preventDefault();if(e.key==='ArrowUp'&&index===0)searchInput.focus();else links[e.key==='Home'?0:e.key==='End'?links.length-1:Math.max(0,Math.min(links.length-1,index+(e.key==='ArrowDown'?1:-1)))]?.focus();});
}
if(page==='studio'){
 const toolIds=new Set(W.catalog.map(t=>t.id));
 function selectTool(id,focus=false){if(!toolIds.has(id))id='prompt';const chooser=$('#studio-chooser');if(chooser)chooser.value=id;$$('[data-studio-tab]').forEach(button=>{const active=button.dataset.studioTab===id;button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1;});$$('.tool-panel').forEach(panel=>panel.hidden=panel.id!==id);if(focus)$('#studio-tab-'+id)?.focus();}
 selectTool(location.hash.slice(1));
 $('#studio-chooser')?.addEventListener('change',e=>{selectTool(e.target.value,true);history.replaceState(null,'','#'+e.target.value);$('#'+e.target.value)?.scrollIntoView({block:'start'});});
 $$('[data-studio-tab]').forEach(button=>{button.addEventListener('click',()=>{selectTool(button.dataset.studioTab);history.replaceState(null,'','#'+button.dataset.studioTab);});button.addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=$$('[data-studio-tab]'),i=tabs.indexOf(button),next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:tabs.length-1))%tabs.length;selectTool(tabs[next].dataset.studioTab,true);history.replaceState(null,'','#'+tabs[next].dataset.studioTab);});});
 window.addEventListener('hashchange',()=>selectTool(location.hash.slice(1)));
 const promptForm=$('#prompt-form'),promptKeys=['topic','type','audience','length','tone','context'];
 const savedPrompt=C.storage.get('th-studio-prompt',null);if(savedPrompt&&typeof savedPrompt==='object')for(const key of promptKeys){if(typeof savedPrompt[key]==='string'&&savedPrompt[key].length<=3000)promptForm.elements.namedItem(key).value=savedPrompt[key];}
 function promptInputs(){return Object.fromEntries(promptKeys.map(key=>[key,promptForm.elements.namedItem(key).value]));}
 promptForm.addEventListener('input',()=>{if(!C.storage.set('th-studio-prompt',promptInputs()))$('#prompt-status').textContent='Chưa giữ được thông tin nhập trên trình duyệt này.';});
 promptForm.addEventListener('submit',e=>{e.preventDefault();try{const result=W.prompt(promptInputs());$('#prompt-result').value=result;$('[data-copy-output="prompt-result"]').disabled=false;$('#download-prompt').disabled=false;$('#prompt-status').textContent='Đã tạo mẫu prompt. Chưa gọi dịch vụ AI.';}catch(err){$('#prompt-status').textContent=err.message;}});
 $('#download-prompt').addEventListener('click',()=>{if($('#prompt-result').value)download('Tech_Horizon_Prompt.txt',$('#prompt-result').value);});
 const transferForm=$('#transfer-form');function calculate(){if(!transferForm.reportValidity())return;try{const result=W.transfer(transferForm.elements.speed.value,transferForm.elements.size.value,transferForm.elements.unit.value,transferForm.elements.loss.value);$('#transfer-time').textContent=W.duration(result.seconds);$('#transfer-effective').textContent=result.effectiveMbps.toLocaleString('vi-VN',{maximumFractionDigits:3});$('#transfer-mbs').textContent=result.megabytesPerSecond.toLocaleString('vi-VN',{maximumFractionDigits:3});$('#transfer-status').textContent='Kết quả theo giả định bạn đã nhập.';}catch(err){$('#transfer-status').textContent=err.message;$('#transfer-time').textContent='—';}}
 transferForm.addEventListener('submit',e=>{e.preventDefault();calculate();});$('#transfer-loss').addEventListener('input',e=>{$('#transfer-loss-value').textContent=e.target.value+'%';});calculate();
 const utmForm=$('#utm-form');utmForm.addEventListener('submit',e=>{e.preventDefault();try{const input=Object.fromEntries(['url','source','medium','campaign','content','term'].map(key=>[key,utmForm.elements[key].value]));$('#utm-result').value=W.utm(input);$('[data-copy-output="utm-result"]').disabled=false;$('#utm-status').textContent='Đã tạo liên kết. Chưa mở hoặc gửi liên kết đi.';}catch(err){$('#utm-status').textContent=err.message;}});
 $$('[data-copy-output]').forEach(button=>button.addEventListener('click',()=>{const field=$('#'+button.dataset.copyOutput);if(field?.value)copy(field.value,field);}));
 const previousChecks=C.storage.get('th-publish-checks',[]),allowed=new Set(W.checks.map(c=>c.id));let checked=new Set(Array.isArray(previousChecks)?previousChecks.filter(id=>allowed.has(id)):[]);
 function renderChecks(){const count=checked.size;$$('[data-publish-check]').forEach(input=>input.checked=checked.has(input.dataset.publishCheck));$('#publish-count').textContent=count+' / '+W.checks.length;$('#publish-bar').style.width=count/W.checks.length*100+'%';$('#publish-status').textContent=count===W.checks.length?'Đã đánh dấu hết các mục tự rà soát.':count?'Còn '+(W.checks.length-count)+' mục để bạn xem lại.':'Bạn chưa đánh dấu mục nào.';}
 $$('.publish-checklist input').forEach(input=>input.addEventListener('change',()=>{const next=new Set(checked);if(input.checked)next.add(input.dataset.publishCheck);else next.delete(input.dataset.publishCheck);if(C.storage.set('th-publish-checks',[...next]))checked=next;else toast('Chưa lưu được dấu chọn.');renderChecks();}));
 $('#reset-checklist').addEventListener('click',()=>{if(!checked.size)return;if(!confirm('Bỏ mọi dấu chọn trong danh sách tự rà soát trên trình duyệt này?'))return;if(C.storage.set('th-publish-checks',[])){checked=new Set();renderChecks();}else toast('Chưa cập nhật được bộ nhớ trình duyệt.');});
 $('#export-checklist').addEventListener('click',()=>download('Tech_Horizon_Ra_Soat_Truoc_Khi_Dang.txt','TECH HORIZON — TỰ RÀ SOÁT TRƯỚC KHI ĐĂNG\n\n'+W.checks.map(item=>(checked.has(item.id)?'[x] ':'[ ] ')+item.group+' — '+item.text).join('\n')+'\n\nDanh sách do bạn tự đánh dấu; không thay thế việc kiểm chứng hoặc đánh giá chuyên môn.\n'));
 renderChecks();
}
})();
